INSERT INTO materi_ajar (id, tingkat_id, nomor, sumber_no, tema, sub_tema, rincian, materi, cakupan, jenis, target_semester, deskripsi, status_promes, keterangan, semester) VALUES ('ma-01942', 'tk-08', 54, '60', 'AKHLAQUL KARIMAH', 'A. Akhlaq', '1. Pribadi', 'Terbiasa melakukan sifat-sifat yang baik : Bersyukur, ta''dhim, ta''at, sabar, dermawan/berbagi, pemaaf, kasih sayang, semangat, tawaduVrendah hati, husnudhon, ramah-tamah, sopan-santun, disiplin, tertib, bersih dan rapih, bicara yang baik/pait madu, papan, empan, adepan, rajin, tekun,dan telaten, taubat, karena alloh, sakdermo, ridlo, tawakkal, qona''ah, menjaga perasaan, keporo ngalah, toleran/tepo seliro, muhasabah/instropeksi diri, menerima diri apa adanya, menerima keadaan orangtua', '1', 'baru', '', '', 'Promes — langsung', '', '1');
INSERT INTO materi_ajar (id, tingkat_id, nomor, sumber_no, tema, sub_tema, rincian, materi, cakupan, jenis, target_semester, deskripsi, status_promes, keterangan, semester) VALUES ('ma-01943', 'tk-08', 55, '61', 'AKHLAQUL KARIMAH', 'A. Akhlaq', '1. Pribadi', 'Terbiasa menjauhi akhlaq tercela : Amarah, dendam, iri hati, bohong, kikir/pelit, serakah/rakus, menghina, mencela, meremehkan, bertengkar, menganiaya, mencuri, menggasap, merusak, jahil/usil, mengumpat/misuh, membully, khianat, riya/pamer, sombong, angkuh, congkak, ujub, egois, tamak, putus asa, su''udhon, menipu, mengancam, mengadu-domba, menghasut, menebar aib, clutak, jajili, menggunjing, bicara jorok, menentang, keras hati/wangkot, niti-niti /sengaja mencari kesalahan orang lain, mendiamkan orang lain, nyatru, memaksa kehendak.', '1', 'baru', '', '', 'Promes — langsung', '', '1');
