INSERT INTO materi_ajar (id, tingkat_id, nomor, sumber_no, tema, sub_tema, rincian, materi, cakupan, jenis, target_semester, deskripsi, status_promes, keterangan, semester) VALUES ('ma-03070', 'tk-10', 77, '53', 'AKHLAQUL KARIMAH', 'A. Akhlaq', '1. Pribadi', 'Terbiasa menjauhi akhlaq tercela : Amarah, dendam, iri hati, bohong, kikir/pelit, serakah/rakus, menghina, mencela, meremehkan, bertengkar, menganiaya, mencuri, menggasap, merusak, jahil/usil, mengumpat/misuh, membully, khianat, riya/pamer, sombong, angkuh, congkak, ujub, egois, tamak, putus asa, su''udhon, menipu, mengancam, mengadu-domba, menghasut, menebar aib, clutak, jajili, menggunjing, bicara jorok, menentang, keras hati/wangkot, niti-niti /sengaja mencari kesalahan orang lain, mendiamkan orang lain, nyatru, memaksa kehendak.', '1-2', 'baru', '', '', 'Promes — kelompok (Sama dengan jenjang sebelumnya)', '', '2');
