INSERT INTO materi_ajar (id, tingkat_id, nomor, sumber_no, tema, sub_tema, rincian, materi, cakupan, jenis, target_semester, deskripsi, status_promes, keterangan, semester) VALUES ('ma-03299', 'tk-11', 68, '92', 'AKHLAQUL KARIMAH', 'A. Akhlaq', '1. Pribadi', 'Terampil melakukan sifat-sifat yang baik: Bersyukur, ta''dhim, ta''at, sabar, dermawan/berbagi, pemaaf, kasih sayang, semangat, tawadu''/rendah hati, husnudhon, ramah-tamah, sopan-santun, disiplin, tertib, bersih dan rapih, bicara yang baik/pait madu, papan, empan, adepan, rajin, tekun, dan telaten, taubat, kama alloh, sakdermo, ridlo, tawakkal, qona''ah, menjaga perasaan, keporo ngalah, toleran /tepo seliro, muhasabah/instropeksi diri, menerima diri apa adanya, menerima keadaan orangtua.', '1', 'baru', '', '', 'Promes — langsung', '', '1');
INSERT INTO materi_ajar (id, tingkat_id, nomor, sumber_no, tema, sub_tema, rincian, materi, cakupan, jenis, target_semester, deskripsi, status_promes, keterangan, semester) VALUES ('ma-03300', 'tk-11', 69, '93', 'AKHLAQUL KARIMAH', 'A. Akhlaq', '1. Pribadi', 'Terampil menjauhi akhlaq tercela: Amarah, dendam, iri hati, bohong, kikir/pelit, serakah/rakus, menghina, mencela, meremehkan, bertengkar, menganiaya, mencuri, menggasap, merusak, jahil/usil, mengumpat/misuh, membully, khianat, riya''/pamer, sombong, angkuh, congkak, ujub, egois, tamak, putus asa, su''udhon, menipu, mengancam, mengadu-domba, menghasut, menebar aib, clutak, jajili, menggunjing, bicara jorok, menentang, keras hati/wangkot, niti-niti/sengaja mencari kesalahan orang lain, mendiamkan orang lain/nyatru, memaksa kehendak.', '1', 'baru', '', '', 'Promes — langsung', '', '1');
INSERT INTO materi_ajar (id, tingkat_id, nomor, sumber_no, tema, sub_tema, rincian, materi, cakupan, jenis, target_semester, deskripsi, status_promes, keterangan, semester) VALUES ('ma-03301', 'tk-11', 70, '94', 'AKHLAQUL KARIMAH', 'A. Akhlaq', '2. Keluarga', 'Terampil berbuat baik kepada orangtua: Ta''at, ta''dhim, bersyukur, tawadu''/rendah hati, perhatian/gemati, ridlo, balas budi, kasih sayang, menerima keadaan orang tua.', '1', 'baru', 'Ta''at, ta''dhim, bersyukur, tawadu''/rendah hati, perhatian/gemati, ridlo, balas budi, kasih sayang, menerima keadaan orangtua', '', 'Promes — langsung', '', '1');
INSERT INTO materi_ajar (id, tingkat_id, nomor, sumber_no, tema, sub_tema, rincian, materi, cakupan, jenis, target_semester, deskripsi, status_promes, keterangan, semester) VALUES ('ma-03302', 'tk-11', 71, '95', 'AKHLAQUL KARIMAH', 'A. Akhlaq', '2. Keluarga', 'Terampil berbuat baik kepada saudara dan kerabat: Rukun, kompak, kerjasama yang baik (enam thobiat luhur), hormat terhadap yang lebih tua, sayang terhadap yang lebih muda, dan pemaaf, perhatian/gemati, kasih sayang.', '1', 'baru', 'Rukun, kompak, kerjasama yang baik (enam thobiat luhur), hormat terhadap yang lebih tua, sayang terhadap yang lebih muda, dan pemaaf, perhatian/gemati, kasih sayang.', '', 'Promes — langsung', '', '1');
