INSERT INTO materi_ajar (id, tingkat_id, nomor, sumber_no, tema, sub_tema, rincian, materi, cakupan, jenis, target_semester, deskripsi, status_promes, keterangan, semester) VALUES ('ma-04263', 'tk-13', 80, '95', 'AKHLAQUL KARIMAH', 'A. Akhlaq', '1. Pribadi', 'Terampil melakukan sifat-sifat yang baik: Bersyukur, ta''dhim, ta''at, sabar, dermawan/berbagi, pemaaf, kasih sayang, semangat, tawadu''/rendah hati, husnudhon, ramah-tamah, sopan-santun, disiplin, tertib, bersih dan rapih, bicara yang baik/pait madu, papan, empan, adepan, rajin, tekun, dan telaten, taubat, kama alloh, sakdermo, ridlo, tawakkal, qona''ah, menjaga perasaan, keporo ngalah, toleran /tepo seliro, muhasabah/instropeksi diri, menerima diri apa adanya, menerima keadaan orangtua.', '1-2', 'baru', '', '', 'Promes — kelompok (Sama dengan jenjang sebelumnya)', '', '1');
INSERT INTO materi_ajar (id, tingkat_id, nomor, sumber_no, tema, sub_tema, rincian, materi, cakupan, jenis, target_semester, deskripsi, status_promes, keterangan, semester) VALUES ('ma-04264', 'tk-13', 81, '96', 'AKHLAQUL KARIMAH', 'A. Akhlaq', '1. Pribadi', 'Terampil menjauhi akhlaq tercela: Amarah, dendam, iri hati, bohong, kikir/pelit, serakah/rakus, menghina, mencela, meremehkan, bertengkar, menganiaya, mencuri, menggasap, merusak, jahil/usil, mengumpat/misuh, membully, khianat, riya''/pamer, sombong, angkuh, congkak, ujub, egois, tamak, putus asa, su''udhon, menipu, mengancam, mengadu-domba, menghasut, menebar aib, clutak, jajili, menggunjing, bicara jorok, menentang, keras hati/wangkot, niti-niti/sengaja mencari kesalahan orang lain, mendiamkan orang lain/nyatru, memaksa kehendak.', '1-2', 'baru', '', '', 'Promes — kelompok (Sama dengan jenjang sebelumnya)', '', '1');
INSERT INTO materi_ajar (id, tingkat_id, nomor, sumber_no, tema, sub_tema, rincian, materi, cakupan, jenis, target_semester, deskripsi, status_promes, keterangan, semester) VALUES ('ma-04265', 'tk-13', 82, '97', 'AKHLAQUL KARIMAH', 'A. Akhlaq', '2. Keluarga', 'Terampil berbuat baik kepada orangtua: Ta''at, ta''dhim, bersyukur, tawadu''/rendah hati, perhatian/gemati, ridlo, balas budi, kasih sayang, menerima keadaan orang tua.', '1-2', 'baru', '', '', 'Promes — kelompok (Sama dengan jenjang sebelumnya)', '', '1');
INSERT INTO materi_ajar (id, tingkat_id, nomor, sumber_no, tema, sub_tema, rincian, materi, cakupan, jenis, target_semester, deskripsi, status_promes, keterangan, semester) VALUES ('ma-04266', 'tk-13', 83, '98', 'AKHLAQUL KARIMAH', 'A. Akhlaq', '2. Keluarga', 'Terampil berbuat baik kepada saudara dan kerabat: Rukun, kompak, kerjasama yang baik (enam thobiat luhur), hormat terhadap yang lebih tua, sayang terhadap yang lebih muda, dan pemaaf, perhatian/gemati, kasih sayang.', '1-2', 'baru', '', '', 'Promes — kelompok (Sama dengan jenjang sebelumnya)', '', '1');
INSERT INTO materi_ajar (id, tingkat_id, nomor, sumber_no, tema, sub_tema, rincian, materi, cakupan, jenis, target_semester, deskripsi, status_promes, keterangan, semester) VALUES ('ma-04267', 'tk-13', 84, '99', 'AKHLAQUL KARIMAH', 'A. Akhlaq', '3. Ulil Amri, Guru & Mubaligh-ot', 'Terampil berbuat baik kepada Ulil Amri: Bersyukur, ta''dhim/hormat, ta''at, tawadu''/rendah hati, husnudhon, senang, sabar, jujur, amanah, taubat, sakdermo, ridlo, pemaaf.', '1-2', 'baru', '', '', 'Promes — kelompok (Sama dengan jenjang sebelumnya)', '', '1');
