INSERT INTO materi_ajar (id, tingkat_id, nomor, sumber_no, tema, sub_tema, rincian, materi, cakupan, jenis, target_semester, deskripsi, status_promes, keterangan, semester) VALUES ('ma-04525', 'tk-13', 84, '98', 'AKHLAQUL KARIMAH', 'A. Akhlaq', '2. Keluarga', 'Terampil berbuat baik kepada saudara dan kerabat: Rukun, kompak, kerjasama yang baik (enam thobiat luhur), hormat terhadap yang lebih tua, sayang terhadap yang lebih muda, dan pemaaf, perhatian/gemati, kasih sayang.', '1-2', 'baru', '', '', 'Promes — kelompok (Sama dengan jenjang sebelumnya)', '', '2');
